using ClaxeDesktop.Core;
using ClaxeDesktop.Platform.Win;
using System.Text.Json;

if (Environment.GetEnvironmentVariable("CLAXE_LAUNCH_PROBE") is { } probe)
{ await File.WriteAllTextAsync(probe, "Launch successful"); return 0; }

var tests = new List<(string Name, Func<Task> Run)>();
void Test(string name, Action action) => tests.Add((name, () => { action(); return Task.CompletedTask; }));
void Check(bool condition, string message = "Assertion failed") { if (!condition) throw new Exception(message); }
void Throws(Action action) { try { action(); } catch (InvalidDataException) { return; } throw new Exception("Expected validation failure"); }
var root = Path.Combine(Path.GetTempPath(), "ClaxeTests-" + Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(root);
var screens = new[] { new MonitorInfo("left", "Left", -1920, 0, 1920, 1040, 1, false), new MonitorInfo("main", "Main", 0, 0, 2560, 1400, 1.5, true) };
Test("Default settings validate", () => new Settings().Validate());
Test("Dock edge validation", () => Throws(() => (new Settings { DockEdge = "invalid" }).Validate()));
Test("Window filter excludes hidden tools and owned popups", () => {
    var normal = new WindowCandidate(true, false, false, false, false, false, false, "App");
    Check(WindowFilter.Include(normal));
    foreach (var excluded in new[] { normal with { Visible = false }, normal with { Cloaked = true }, normal with { ToolWindow = true }, normal with { Owned = true }, normal with { OwnProcess = true }, normal with { NoActivate = true }, normal with { Title = "" } }) Check(!WindowFilter.Include(excluded));
    Check(WindowFilter.Include(normal with { Owned = true, AppWindow = true }));
});
Test("Ten windows group by case insensitive executable", () => { var list = Enumerable.Range(1, 10).Select(i => new AppWindow(i, (uint)i, "Test", i % 2 == 0 ? @"C:\Apps\TEST.exe" : @"c:\apps\test.exe", false)).ToList(); Check(WindowGrouping.Build(list, true).Count == 1); Check(WindowGrouping.Build(list, false).Count == 10); });
Test("Unknown process identity does not merge unrelated apps", () => Check(WindowGrouping.Build(new[] { new AppWindow(1, 1, "A", null, false), new AppWindow(2, 2, "B", null, false) }, true).Count == 2));
Test("Hosted UWP windows are not incorrectly merged", () => Check(WindowGrouping.Build(new[] { new AppWindow(1, 1, "A", @"C:\Windows\System32\ApplicationFrameHost.exe", false), new AppWindow(2, 1, "B", @"C:\Windows\System32\ApplicationFrameHost.exe", false) }, true).Count == 2));
Test("Group click cycles and tolerates closed previous window", () => { var list = new[] { new AppWindow(1, 1, "A", null, false), new AppWindow(2, 1, "B", null, true) }; Check(WindowGrouping.Next(list, 1)?.Handle == 2); Check(WindowGrouping.Next(list, 2)?.Handle == 1); Check(WindowGrouping.Next(list, 99)?.Handle == 1); Check(WindowGrouping.Next([], 0) is null); });
Test("Auto hide protects pointer keyboard menus and dragging", () => {
    var delay = TimeSpan.FromSeconds(1);
    Check(DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "floating", false, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", true, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, true, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, true, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, true, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, false, TimeSpan.FromMilliseconds(200)));
});
Test("Closed native window activation fails gracefully", () => Check(!new WindowsWindowService().Activate(new(0, 0, "Closed", null, false))));
Test("Out-of-range appearance rejected", () => Throws(() => (new Settings { Opacity = .1 }).Validate()));
Test("Non-finite opacity rejected", () => Throws(() => (new Settings { Opacity = double.NaN }).Validate()));
Test("Invalid layout rejected", () => Throws(() => (new Settings { Panel = new("main", double.PositiveInfinity, 2) }).Validate()));
Test("Unsupported schema rejected", () => Throws(() => (new Settings { SchemaVersion = 99 }).Validate()));
Test("Remote and command launch blocked", () => { Check(!LaunchPolicy.IsAllowed("https://example.com")); Check(!LaunchPolicy.IsAllowed(@"\\server\file.exe")); Check(!LaunchPolicy.IsAllowed(@"C:\temp\run.cmd")); Check(!LaunchPolicy.IsAllowed("calc.exe")); });
Test("Local executable and shortcut accepted", () => { Check(LaunchPolicy.IsAllowed(@"C:\Windows\notepad.exe")); Check(LaunchPolicy.IsAllowed(@"C:\Apps\test.LNK")); });
Test("Null shortcut collection rejected", () => Throws(() => (new Settings { Shortcuts = null! }).Validate()));
Test("Monitor remap retains stored identity", () => { var saved = new Placement("missing", 200, 200); var result = LayoutEngine.Resolve(saved, screens, 300, 200, 0, 0, false); Check(result.Monitor.Id == "main"); Check(saved.MonitorId == "missing"); });
Test("Negative-origin screen chosen by identity", () => Check(LayoutEngine.Resolve(new("left", 100, 200), screens, 300, 200, 0, 0, false).Monitor.X == -1920));
Test("DPI clamp keeps panel in work area", () => { var p = LayoutEngine.Resolve(new("main", 9999, 9999), screens, 300, 200, 0, 0, false); Check(Math.Abs(p.X - (2560 / 1.5 - 300)) < .01); Check(p.Y <= 1400 / 1.5 - 200); });
Test("Grid snaps to 12 DIP", () => { var p = LayoutEngine.Resolve(new("left", 19, 29), screens, 300, 200, 0, 0, true); Check(p.X == 24 && p.Y == 24); });
Test("Oversized window clamps to origin", () => { var p = LayoutEngine.Resolve(new("left", -100, 500), screens, 3000, 2000, 0, 0, false); Check(p.X == 0 && p.Y == 0); });
tests.Add(("Atomic settings roundtrip", async () => { var store = new SettingsStore(Path.Combine(root, "roundtrip")); var input = new Settings { IconSize = 64, Panel = new("left", 200, 220) }; await store.SaveAsync(input); var read = await store.LoadAsync(); Check(read.Settings.IconSize == 64 && read.Settings.Panel == input.Panel); Check(!File.Exists(store.FilePath + ".tmp")); }));
tests.Add(("Corrupt primary recovers backup", async () => { var store = new SettingsStore(Path.Combine(root, "backup")); await store.SaveAsync(new() { IconSize = 32 }); await store.SaveAsync(new() { IconSize = 64 }); await File.WriteAllTextAsync(store.FilePath, "{broken"); var loaded = await store.LoadAsync(); Check(loaded.Settings.IconSize == 32 && loaded.Notice is not null); await store.SaveAsync(loaded.Settings); Check(JsonDocument.Parse(await File.ReadAllTextAsync(store.FilePath + ".bak")).RootElement.GetProperty("IconSize").GetInt32() == 32); }));
tests.Add(("Future schema preserved read-only", async () => { var store = new SettingsStore(Path.Combine(root, "future")); Directory.CreateDirectory(Path.GetDirectoryName(store.FilePath)!); await File.WriteAllTextAsync(store.FilePath, "{\"SchemaVersion\":999}"); var loaded = await store.LoadAsync(); Check(loaded.ReadOnly); Check((await File.ReadAllTextAsync(store.FilePath)).Contains("999")); }));
tests.Add(("Canceled write preserves last good config", async () => { var store = new SettingsStore(Path.Combine(root, "cancel")); await store.SaveAsync(new() { IconSize = 32 }); using var cts = new CancellationTokenSource(); cts.Cancel(); try { await store.SaveAsync(new() { IconSize = 64 }, cts.Token); } catch (OperationCanceledException) { } Check((await store.LoadAsync()).Settings.IconSize == 32); }));
tests.Add(("Concurrent writes leave valid JSON", async () => { var store = new SettingsStore(Path.Combine(root, "concurrent")); await Task.WhenAll(Enumerable.Range(24, 20).Select(i => store.SaveAsync(new() { IconSize = i }))); (await store.LoadAsync()).Settings.Validate(); }));
Test("Crash marker detects dirty exit and clears", () => { var recovery = new RecoveryService(Path.Combine(root, "recovery")); Check(!recovery.Begin()); Check(recovery.Begin()); recovery.Complete(); Check(!recovery.Begin()); recovery.Complete(); });
Test("Log excludes exception message and paths", () => { var dir = Path.Combine(root, "logs"); new LocalLog(dir).Write("test", new IOException("secret path and password")); var content = File.ReadAllText(Path.Combine(dir, "events.jsonl")); Check(!content.Contains("secret")); Check(content.Contains("IOException")); });
Test("Windows monitors return real work areas", () => { var found = new WindowsMonitorService().GetMonitors(); Check(found.Count > 0); Check(found.Any(m => m.Primary)); Check(found.All(m => m.Width > 0 && m.Height > 0 && m.Scale > 0)); Console.WriteLine("  Monitors: " + string.Join("; ", found.Select(m => m.ToString()))); });
tests.Add(("Windows memory and CPU measurements", async () => { var metrics = new WindowsMetrics(); var first = metrics.Sample(); Check(first.Cpu is null); await Task.Delay(250); var sample = metrics.Sample(); Check(sample.Cpu is >= 0 and <= 100 && sample.Memory is >= 0 and <= 100 && sample.TotalGb > 0); Console.WriteLine($"  CPU={sample.Cpu:0.0}% RAM={sample.UsedGb:0.0}/{sample.TotalGb:0.0}GB"); }));
Test("Catalog exposes only implemented unique settings", () => { Check(SettingsCatalog.Supported.Count == 27, "catalog count " + SettingsCatalog.Supported.Count); Check(SettingsCatalog.Supported.Select(d => d.Key).Distinct().Count() == 27); foreach (var d in SettingsCatalog.Supported) Check(SettingsCatalog.Value(new(), d.Key) is not null); Check(!SettingsCatalog.Supported.Any(d => d.Key == "privacy.allowWidgetNetwork")); });
Test("Catalog numeric bounds validate against runtime model", () => { foreach (var d in SettingsCatalog.Supported.Where(d => d.Kind == "number")) { SettingsCatalog.Apply(new(), d.Key, d.Minimum).Validate(); SettingsCatalog.Apply(new(), d.Key, d.Maximum).Validate(); Throws(() => SettingsCatalog.Apply(new(), d.Key, d.Maximum + 1)); } });
Test("Catalog search handles Turkish labels descriptions and keys", () => { Check(SettingsCatalog.Supported.Single(d => d.Key == "appearance.surfaceOpacity").Matches("OPAK")); Check(SettingsCatalog.Supported.Single(d => d.Key == "dock.iconSizeDip").Matches("dock.iconSizeDip")); Check(SettingsCatalog.Supported.Single(d => d.Key == "panels.widthDip").Matches("genişliği ekran")); });
Test("Unsupported or wrong-typed settings rejected", () => { Throws(() => SettingsCatalog.Apply(new(), "privacy.allowWidgetNetwork", true)); Throws(() => SettingsCatalog.Apply(new(), "dock.autoHide", "true")); Throws(() => SettingsCatalog.Apply(new(), "dock.iconSizeDip", 32.5)); Throws(() => SettingsCatalog.Apply(new(), "themes.panelStyle", "unsupported")); });
Test("Theme selection clears previous custom accents", () => { var s = SettingsCatalog.Apply(new() { PrimaryAccent = "#123456" }, "themes.activeTheme", "tempest"); Check(s.PrimaryAccent is null && ThemePresets.Resolve(s).Accent == "#64BFFF"); });
Test("Three preset palettes have readable text contrast", () => {
    double Lum(string hex) { var channels = new[] { 1, 3, 5 }.Select(i => Convert.ToInt32(hex.Substring(i, 2), 16) / 255.0).Select(c => c <= .04045 ? c / 12.92 : Math.Pow((c + .055) / 1.055, 2.4)).ToArray(); return .2126 * channels[0] + .7152 * channels[1] + .0722 * channels[2]; }
    foreach (var p in ThemePresets.All) { Check((Lum(p.Text) + .05) / (Lum(p.Surface) + .05) >= 7); Check((Lum(p.Muted) + .05) / (Lum(p.Surface) + .05) >= 4.5); }
});
Test("Color inputs require full six digit RGB", () => { Throws(() => SettingsCatalog.Apply(new(), "appearance.accentPrimary", "#FFF")); Throws(() => SettingsCatalog.Apply(new(), "appearance.accentPrimary", "transparent")); Check(ThemePresets.IsColor("#aBcD09")); });
Test("Theme JSON roundtrip contains no personal asset paths", () => { var s = new Settings { ThemeId = "sakura", Material = "neon", PrimaryAccent = "#C0FFEE", Shortcuts = [new("Private", @"C:\private\secret.exe")] }; var text = ThemeFiles.Serialize(s); Check(!text.Contains("secret") && !text.Contains("Shortcuts")); var loaded = ThemeFiles.Parse(text).ApplyTo(new()); Check(loaded.ThemeId == "sakura" && loaded.PrimaryAccent == "#C0FFEE" && loaded.Material == "neon"); });
Test("Theme import preserves shortcuts placement and behavior", () => { var current = new Settings { Panel = new("saved", 24, 48), IconSize = 64, Shortcuts = [new("App", @"C:\test\app.exe")] }; var next = new ThemeConfiguration { ThemeId = "tempest" }.ApplyTo(current); Check(next.Panel == current.Panel && next.Shortcuts == current.Shortcuts && next.IconSize == 64); });
Test("Malformed unknown oversized or future theme files rejected", () => { foreach (var text in new[] { "{broken", "[]", "{}", "{\"Kind\":\"ClaxeDesktop.Theme\",\"SchemaVersion\":99,\"ThemeId\":\"tempest\"}", "{\"Kind\":\"ClaxeDesktop.Theme\",\"SchemaVersion\":1,\"ThemeId\":\"tempest\",\"Path\":\"../escape\"}", "{\"Kind\":\"ClaxeDesktop.Theme\",\"SchemaVersion\":1,\"ThemeId\":\"tempest\",\"ThemeId\":\"sakura\"}", new string(' ', 33000) }) Throws(() => ThemeFiles.Parse(text)); });
Test("Category reset preserves unrelated settings", () => { var s = new Settings { ThemeId = "sakura", IconSize = 80, DockOnTop = true, Panel = new("saved", 24, 48) }; var result = SettingsCatalog.Reset(s, ["dock.iconSizeDip", "dock.alwaysOnTop"]); Check(result.IconSize == 48 && !result.DockOnTop && result.ThemeId == "sakura" && result.Panel == s.Panel); });
Test("Undo redo supports branch and bounded history", () => { var history = new SettingsHistory(2); var a = new Settings(); var b = a with { IconSize = 64 }; var c = b with { IconSize = 72 }; history.Push(a); history.Push(b); Check(history.Undo(c) == b); Check(history.Redo(b) == c); history.Push(c); Check(history.Undo(a) == c); history.Push(a); Check(!history.CanRedo); history.Clear(); Check(!history.CanUndo); });
Test("Configurable grid and hide delay affect decisions", () => { var p = LayoutEngine.Resolve(new("left", 19, 29), screens, 300, 200, 0, 0, true, 32); Check(p.X == 32 && p.Y == 32); Check(DockVisibilityPolicy.Collapse(true, "top", false, false, false, false, TimeSpan.FromMilliseconds(250), 200)); Check(!DockVisibilityPolicy.Collapse(true, "top", false, false, false, false, TimeSpan.FromMilliseconds(250), 1000)); });
