Test("Wallpaper palette follows the dominant vivid hue, stays readable and falls back for grey images", () => {
    static double Hue(string hex) => WallpaperPalette.ToHsl(Convert.ToByte(hex[1..3], 16), Convert.ToByte(hex[3..5], 16), Convert.ToByte(hex[5..7], 16)).H;
    var pixels = new List<(byte R, byte G, byte B)>();
    for (int i = 0; i < 700; i++) pixels.Add((30, 90, 220));
    for (int i = 0; i < 250; i++) pixels.Add((230, 60, 120));
    for (int i = 0; i < 300; i++) pixels.Add((12, 12, 14));
    var palette = WallpaperPalette.Generate(pixels);
    Check(Hue(palette.Accent) is > 210 and < 232, "accent hue " + Hue(palette.Accent));
    Check(Hue(palette.Secondary) is > 325 and < 352, "secondary hue " + Hue(palette.Secondary));
    ThemePresets.ValidateCustom(palette);
    var grey = WallpaperPalette.Generate(Enumerable.Repeat(((byte)128, (byte)128, (byte)128), 500).ToList());
    Check(Math.Abs(Hue(grey.Accent) - WallpaperPalette.FallbackHue) < 6, "fallback hue " + Hue(grey.Accent));
    var settings = new Settings { ThemeId = ThemePresets.WallpaperId, CustomPalette = palette }; settings.Validate(); Check(ThemePresets.Resolve(settings).Accent == palette.Accent);
    Throws(() => new Settings { ThemeId = ThemePresets.WallpaperId }.Validate());
    Throws(() => new Settings { ThemeId = ThemePresets.WallpaperId, CustomPalette = palette with { Text = palette.Surface } }.Validate());
});
