Test("Rice import rejects extra files, folders, missing media, unknown fields and other kinds", () => {
    var dir = Path.Combine(root, "rice-bad"); Directory.CreateDirectory(dir);
    var good = RiceFiles.Serialize(RiceFiles.Capture(new Settings(), "x", DateTimeOffset.Now, false, null, false, null));
    string Zip(string name, params (string Entry, string Content)[] entries)
    {
        var path = Path.Combine(dir, name);
        using (var zip = System.IO.Compression.ZipFile.Open(path, System.IO.Compression.ZipArchiveMode.Create))
            foreach (var (entry, content) in entries) using (var writer = new StreamWriter(zip.CreateEntry(entry).Open())) writer.Write(content);
        return path;
    }
    Throws(() => RiceFiles.Read(Zip("extra.noxrice", ("rice.json", good), ("run.exe", "MZ")), Path.Combine(dir, "o1")));
    Throws(() => RiceFiles.Read(Zip("folder.noxrice", ("../rice.json", good)), Path.Combine(dir, "o2")));
    Throws(() => RiceFiles.Read(Zip("missing.noxrice", ("rice.json", good.Replace("\"Wallpaper\": null", "\"Wallpaper\": \"wallpaper.png\""))), Path.Combine(dir, "o3")));
    Throws(() => RiceFiles.Parse(good.Replace("\"Name\":", "\"Script\": \"x\", \"Name\":")));
    Throws(() => RiceFiles.Parse(good.Replace("Noxelyra.Rice", "Other")));
    Check(!Directory.Exists(Path.Combine(dir, "o1")));
});
