Console.WriteLine($"Tests: {selectedTests.Count}; passed: {selectedTests.Count - failed}; failed: {failed}");
// The generated, uniquely named test directory contains no user data.
if (!string.Equals(Path.GetDirectoryName(Path.GetFullPath(root)), Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase) || !Path.GetFileName(root).StartsWith("ClaxeTests-")) throw new InvalidOperationException("Unsafe test cleanup path");
Directory.Delete(root, true);
return failed == 0 ? 0 : 1;

sealed class FakeLook : IWindowsLookService
{
    private readonly Dictionary<string, LookValue> values = [];
    public int Broadcasts, Writes;
    public void Set(LookValue value) => values[value.Id] = value;
    public LookValue Get(string key, string name) => Read(key, name);
    public LookValue Read(string key, string name) => values.GetValueOrDefault(key + "\\" + name) ?? new(key, name, false);
    public void Write(LookValue value) { Writes++; if (value.Exists) values[value.Id] = value; else values.Remove(value.Id); }
    public void Broadcast() => Broadcasts++;
}

sealed class FakeServices : IServiceControl
{
    public readonly Dictionary<string, ServiceState> States = new(StringComparer.OrdinalIgnoreCase);
    public bool FailStart;
    public ServiceState Read(string name) => States[name];
    public void SetStart(string name, ServiceStart start) => States[name] = States[name] with { Start = start };
    public void Stop(string name) => States[name] = States[name] with { Running = false };
    public void Start(string name) { if (FailStart) throw new InvalidOperationException("start failed"); States[name] = States[name] with { Running = true }; }
}
